package android.content; import java.util.*; public class Intent { public static final String ACTION_SEND="android.intent.action.SEND",ACTION_SEND_MULTIPLE="android.intent.action.SEND_MULTIPLE"; public static final int FLAG_ACTIVITY_CLEAR_TOP=0x04000000; final Map<String,Object> extras=new HashMap<>(); String action; int flags; public Intent(){} public Intent(Context c,Class<?> t){} public Intent(Intent i){extras.putAll(i.extras);action=i.action;flags=i.flags;} public Intent putExtras(Intent other){extras.putAll(other.extras);return this;} public Intent setAction(String s){action=s;return this;} public String getAction(){return action;} public String getStringExtra(String n){return (String)extras.get(n);} public Intent putExtra(String n,int v){extras.put(n,v);return this;} public Intent putExtra(String n,long v){extras.put(n,v);return this;} public Intent putExtra(String n,String v){extras.put(n,v);return this;} public Intent addFlags(int f){flags|=f;return this;} public Intent setFlags(int f){flags=f;return this;}public int getFlags(){return flags;}public void removeExtra(String n){extras.remove(n);} public boolean hasExtra(String n){return extras.containsKey(n);} public int getIntExtra(String n,int d){return extras.containsKey(n)?((Number)extras.get(n)).intValue():d;} public long getLongExtra(String n,long d){return extras.containsKey(n)?((Number)extras.get(n)).longValue():d;} }
